import {esc,thumbnail} from './shared.js';
import {outfitFilters,outfitStyles,outfitTitle,outfitSeasonName,outfitStyleNames} from '../outfit-model.js';
import {displayCode} from '../communication-codes.js';
import {isActiveGarment,isPendingDiscard} from '../garment-status.js';
import {isReconstructed,imageNotice} from '../garment-image.js';
import {basicName} from '../assumed-basics.js';
import {groupedGarments,garmentGroup,canonicalGarmentGroup} from '../garment-model.js';
import {outfitsForGarment} from '../outfit-relationships.js';
import {dataStatus} from './data-status.js';
import {closetOverview} from '../closet-overview.js';

export const moods=[{id:'all',name:'随心看看'},{id:'relaxed',name:'松弛一下'},{id:'minimal',name:'利落出门'},{id:'street',name:'叠穿一点'}];
export function refinedMixFilters(outfits,{season='all',style='all'}={}){
 const filters=outfitFilters(outfits,{season}),selected=outfitStyles.some(s=>s.id===style)?style:'all';
 return {...filters,style:selected,visible:filters.inSeason.filter(o=>selected==='all'||o.styleTags?.includes(selected))};
}
export const shortTitle=o=>outfitTitle(o).split('｜').at(-1).trim();
const url=p=>p?.startsWith('/')?p:'/'+p;
const photo=o=>`<img src="${esc(url(o.visual.src))}" alt="${esc(o.visual.alt||outfitTitle(o))}" width="1024" height="1536" loading="lazy">`;
const imageLabel=o=>[o.visual?.kind==='ai'?'AI示意':o.visual?'穿着照片':'衣物组合',o.outfitKind==='planned'?'含未购单品':'',o.assumedBasics?.length?'含假设内搭':''].filter(Boolean).join(' · ');
const pieceImage=i=>`<img src="${esc(url(thumbnail(i)))}" alt="${esc(i.name)}" width="400" height="500" loading="lazy">`;
const href=(page,{season='all',style='all'}={})=>{const q=new URLSearchParams();if(season!=='all')q.set('season',season);if(style!=='all')q.set('style',style);return '#'+page+(q.size?'?'+q:'');};
function seasonOptions(page,filters){return `<nav class="moods" aria-label="季节范围">${[{id:'all',name:'所有季节'},...filters.seasons].map(s=>`<a href="${href(page,{season:s.id,style:filters.style})}" data-filter-link data-filter-key="season:${s.id}" ${filters.season===s.id?'aria-current="page"':''}>${s.name}</a>`).join('')}</nav>`;}
function styleOptions(filters){return `<nav class="moods" aria-label="搭配风格">${[{id:'all',name:'全部风格'},...outfitStyles].map(s=>`<a href="${href('outfits',{season:filters.season,style:s.id})}" data-filter-link data-filter-key="style:${s.id}" ${filters.style===s.id?'aria-current="page"':''}>${s.name}</a>`).join('')}</nav>`;}
function cards(outfits){return outfits.map(o=>`<article class="look" data-outfit-id="${esc(o.id)}"><button class="look-image" data-outfit="${esc(o.id)}" aria-label="查看搭配 ${esc(o.code||o.id)}">${o.visual?photo(o):'<span class="no-visual">查看衣物组合 ↗</span>'}</button><div class="look-copy"><span class="look-code">${esc(o.code||'')}</span><h2><button data-outfit="${esc(o.id)}" title="${esc(outfitTitle(o))}">${esc(shortTitle(o))}</button></h2><span class="visual-label">${esc(imageLabel(o))}</span></div></article>`).join('');}
const empty=()=>'<div class="empty"><p>这个范围暂时没有搭配，试试其他范围。</p></div>';

export function savedOutfitsView({outfits,season='all',style='all'}){
 const filters=refinedMixFilters(outfits,{season,style});
 return `<section class="page-heading"><div><h1>我的搭配</h1><p>喜欢的穿法，都在这里。</p></div><span class="list-count" role="status">${filters.visible.length}套搭配</span></section><div class="browse-filters"><div class="filter-row"><span class="filter-label">季节</span>${seasonOptions('outfits',filters)}</div><div class="filter-row"><span class="filter-label">风格</span>${styleOptions(filters)}<span class="subtle order-note">按已保存的顺序浏览</span></div></div><section class="look-grid" aria-label="已保存的搭配">${cards(filters.visible)||empty()}</section>`;
}
export function mixView({filters,batch}){
 const batchLabel=batch.batchNumber<=1?'随机推荐':`第${batch.batchNumber}批`;
 return `<section class="page-heading"><div><h1>今天，穿什么心情？</h1><p>衣橱没变，换个心情。</p></div><span class="list-count" role="status" aria-live="polite" aria-atomic="true">${batchLabel} · ${batch.outfits.length}套 / ${batch.total}套</span></section><div class="browse-filters"><div class="filter-row"><span class="filter-label">心情</span><nav class="moods" aria-label="选择穿衣心情">${moods.map(m=>`<a href="${href('mix',{season:filters.season,style:m.id})}" data-mood="${m.id}" data-filter-link data-filter-key="mood:${m.id}" ${filters.style===m.id?'aria-current="page"':''}>${m.name}</a>`).join('')}</nav></div><div class="filter-row"><span class="filter-label">季节</span>${seasonOptions('mix',filters)}<button class="primary shuffle-next" data-next ${batch.canAdvance?'':'disabled'}>换一批 <span aria-hidden="true">↻</span></button></div></div><section class="look-grid" aria-label="这一批搭配">${cards(batch.outfits)||empty()}</section>${batch.total>0&&!batch.canAdvance?`<p class="small-pool">这个范围只有${batch.total}套，已全部展示。可以扩大范围再看看。</p>`:''}`;
}
export function closetView({items,layer='all',group='all',usage='all',usageCounts=null,personalStatus='ready',pending=false,overview=false}){
 const showOverview=overview&&!pending;
 const active=items.filter(pending?isPendingDiscard:isActiveGarment),options=[['all','全部'],['outer','外层'],['inner','内搭'],['bottom','下装'],['shoes','鞋'],['accessory','配饰']],page=pending?'discard':'closet';
 const selected=options.some(([id])=>id===layer)?layer:'all',candidates=active.filter(i=>selected==='all'||i.layer===selected),groups=groupedGarments(candidates),requested=canonicalGarmentGroup(group),selectedGroup=groups.some(g=>g.id===requested)?requested:'all';
 const inGroup=candidates.filter(i=>selectedGroup==='all'||garmentGroup(i).id===selectedGroup),selectedUsage=!showOverview&&!pending&&['unused','low'].includes(usage)?usage:'all',known=selectedUsage==='all'||usageCounts!==null;
 const visible=inGroup.filter(i=>selectedUsage==='all'||usageCounts&&(selectedUsage==='unused'?(usageCounts.get(i.id)||0)===0:(usageCounts.get(i.id)||0)>=1&&(usageCounts.get(i.id)||0)<=2));
 const pendingCount=items.filter(isPendingDiscard).length;
 const secondary=pending?'<a class="quiet-link" href="#closet">← 我的衣橱</a>':`<a class="quiet-link" href="#discard">准备丢弃 · ${pendingCount}</a>`;
 const filters=`<details class="scope closet-filter"><summary>筛选 <span aria-hidden="true">⌄</span>${selectedGroup!=='all'||selectedUsage!=='all'?'<i class="filter-active" aria-label="已筛选"></i>':''}</summary><div class="scope-content"><label class="select-field"><span>子类</span><select data-closet-filter="group" aria-label="衣物子类"><option value="all">全部子类</option>${groups.map(g=>`<option value="${esc(g.id)}" ${selectedGroup===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label>${!pending?`<label class="select-field"><span>搭配引用</span><select data-closet-filter="usage" aria-label="搭配引用情况">${[['all','全部衣物'],['unused','未用到'],['low','仅用在1–2套']].map(([id,name])=>`<option value="${id}" ${selectedUsage===id?'selected':''}>${name}</option>`).join('')}</select></label><p>按已保存搭配引用统计，不是实际穿着次数。</p>`:''}</div></details>`;
 return `<section class="page-heading"><div><h1>${pending?'准备丢弃':showOverview?'衣橱概览':'我的衣橱'}</h1><p>${pending?'暂不参与新搭配，衣物档案和编号仍保留。':showOverview?'衣物的类别与色系，一眼看清。':'熟悉的衣服，还有新的穿法。'}</p></div><div class="closet-heading-tools"><span class="list-count" role="status">${showOverview?active.length+'件在用衣物':known?visible.length+'件衣物':'搭配关联暂未读取'}</span>${secondary}</div></section><div class="closet-toolbar"><nav class="moods closet-tabs" aria-label="衣物分类">${options.map(([id,name])=>`<a href="#${page}${id==='all'?'':'?layer='+id}" data-filter-link data-filter-key="layer:${id}" ${!showOverview&&selected===id?'aria-current="page"':''}>${name}</a>`).join('')}${!pending?`<a href="#closet?view=overview" data-filter-link data-filter-key="view:overview" ${showOverview?'aria-current="page"':''}>衣橱概览</a>`:''}</nav>${showOverview?'':filters}</div>${showOverview?closetOverview(items):!known?dataStatus('personal','搭配关联',personalStatus==='loading'?'loading':'error'):`<section class="garment-grid">${visible.map(i=>`<article class="garment" data-garment-id="${esc(i.id)}"><button class="garment-image" data-garment="${esc(i.id)}" aria-label="查看衣物 ${esc(displayCode(i))}">${pieceImage(i)}</button><div class="garment-copy"><span>${esc(displayCode(i))}</span><h2><button data-garment="${esc(i.id)}" title="${esc(i.name)}">${esc(i.name)}</button></h2></div>${isReconstructed(i)?`<span class="garment-evidence" title="${esc(imageNotice)}">AI整理示意</span>`:''}</article>`).join('')||'<p class="empty">这个范围暂时没有衣物。</p>'}</section>`}`;
}
const close=dialog=>`<button class="close" data-close="${dialog}" aria-label="关闭${dialog==='outfit-detail'?'搭配':'衣物'}详情">×</button>`;
const ownershipNotes=outfit=>(outfit.outfitKind==='planned'?`<div class="ownership-note"><h3>尚未配齐</h3>${(outfit.suggestedPieces||[]).map(p=>`<p>${esc(p.name)} · 未购</p>`).join('')}<p>以上单品未计入衣橱。</p></div>`:'')+(outfit.assumedBasics?.length?`<div class="ownership-note"><h3>含假设基础内搭</h3>${outfit.assumedBasics.map(b=>`<p>${esc(basicName(b))} · ${esc(b.exposure)}</p>`).join('')}<p>按已授权的假设展示，未计入衣橱。</p></div>`:'');
export function outfitDetailView(outfit,items,{asPage=false,catalogStatus='ready',relationships=null}={}){
 const members=Object.values(outfit.selection||{}).map(id=>items.find(i=>i.id===id)).filter(Boolean);
 const origin=relationships?.origins.find(r=>r.outfitId===outfit.id),derived=origin?.available?`<p class="origin-note">由 <a href="#outfits/${encodeURIComponent(origin.sourceId)}">${esc(origin.sourceCode||origin.sourceTitle)}</a> 延伸</p>`:outfit.derivedFromOutfitId?'<p class="origin-note">原搭配关联保留在档案中。</p>':'';
 return `${asPage?'':close('outfit-detail')}<div class="detail-visual">${outfit.visual?`<button class="detail-zoom" data-outfit-image="${esc(outfit.id)}" aria-label="放大搭配 ${esc(outfit.code||outfit.id)}">${photo(outfit)}<span>放大 ↗</span></button>`:'<p>这套搭配暂时没有配图。</p>'}</div><section class="detail-copy"><span class="detail-code">${esc(outfit.code)} · ${outfitSeasonName(outfit.season)} · ${outfitStyleNames(outfit).join(' / ')}</span><h2 id="outfit-title">${esc(shortTitle(outfit))}</h2><p class="detail-image-label">${esc(imageLabel(outfit))} · 细节与合身度以实物为准</p><h3>图里这样穿</h3>${outfit.wearingNotes?.length?`<ul>${outfit.wearingNotes.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:'<p>这套尚未补充穿法说明。</p>'}<h3>这套用到的衣物</h3>${catalogStatus==='ready'?`<div class="detail-pieces">${members.map(i=>`<button data-garment="${esc(i.id)}" aria-label="查看衣物 ${esc(displayCode(i))}">${pieceImage(i)}<span>${esc(displayCode(i))}</span></button>`).join('')}</div>`:dataStatus('catalog','衣物档案',catalogStatus)}${derived}${ownershipNotes(outfit)}</section>`;
}
export function garmentDetailView(item,outfits,{relationships=null,personalStatus='ready'}={}){
 const related=personalStatus==='ready'?outfitsForGarment(item.id,outfits,relationships):null;
 return `${close('garment-detail')}<div class="detail-visual garment-detail-image">${pieceImage(item)}</div><section class="detail-copy"><span class="detail-code">${esc(displayCode(item))}</span><h2 id="garment-title">${esc(item.name)}</h2><p>${esc(item.subtype)} · ${esc(item.color?.name)}</p>${isReconstructed(item)?`<p class="image-evidence">AI整理示意 · ${esc(imageNotice)}</p>`:''}${isPendingDiscard(item)?'<p class="image-evidence">暂不参与新搭配，档案与已有搭配关联仍保留。</p>':''}${related===null?dataStatus('personal','搭配关联',personalStatus==='loading'?'loading':'error'):`<h3>出现在${related.length}套已保存搭配中</h3><div class="related-looks">${related.map(o=>`<button data-related-outfit="${esc(o.id)}" aria-label="查看搭配 ${esc(o.code||o.id)}">${o.visual?photo(o):'<span>衣物组合</span>'}<span>${esc(o.code)} · ${esc(shortTitle(o))}${o.outfitKind==='planned'?' · 含未购单品':''}</span></button>`).join('')||'<p>暂时没有已保存的搭配。</p>'}</div><p class="image-evidence">按已保存搭配的关联统计，不是实际穿着次数。</p>`}</section>`;
}
export function outfitZoomView(outfit){return `<button class="close" data-close="outfit-image" aria-label="关闭搭配大图">×</button><h2 id="outfit-image-title">${esc(outfit.code)} · ${esc(shortTitle(outfit))}</h2>${photo(outfit)}<p>${esc(imageLabel(outfit))} · 不是本人试穿，细节以实物为准。</p>${ownershipNotes(outfit)}`;}
export function personalNotesView(saved){return `<section class="page-heading"><div><h1>搭配笔记</h1><p>自己的穿法，慢慢留下来。</p></div><a class="quiet-link" href="#outfits">← 我的搭配</a></section><div class="personal-notes">${saved.map(n=>`<article><h2>${esc(n.title)}</h2><p>${esc(n.text)}</p></article>`).join('')||'<p class="empty">还没有搭配笔记。</p>'}</div>`;}
